requests.testScript:
pw.test("status 200", () => { pw.expect(pw.response.status).toBe(200); });
pw.test("code service_healthy", () => { pw.expect(pw.response.body.code).toBe("service_healthy"); });
pw.test("status ok", () => { pw.expect(pw.response.body.data.status).toBe("ok"); });

pw.test("status 200", () => { pw.expect(pw.response.status).toBe(200); });
pw.test("code specialty_list", () => { pw.expect(pw.response.body.code).toBe("specialty_list"); });
const data = pw.response.body.data;
pw.test("data es lista", () => { pw.expect(Array.isArray(data)).toBe(true); });
pw.test("son diez especialidades", () => { pw.expect(data.length).toBe(10); });
pw.test("cada entrada trae sus keywords", () => { data.forEach(s => pw.expect(Array.isArray(s.keywords)).toBe(true)); });
pw.test("la variable SPECIALTY pertenece al catalogo", () => { pw.expect(data.map(s => s.specialty)).toInclude(pw.env.get("SPECIALTY")); });

pw.test("status 200", () => { pw.expect(pw.response.status).toBe(200); });
pw.test("code place_list", () => { pw.expect(pw.response.body.code).toBe("place_list"); });
const m = pw.response.body.meta.pagination;
pw.test("meta.pagination completa", () => { ["page","pageSize","totalItems","totalPages"].forEach(k => pw.expect(m[k]).not.toBe(undefined)); });
pw.test("data no excede pageSize", () => { pw.expect(pw.response.body.data.length <= m.pageSize).toBe(true); });

pw.test("status 200", () => { pw.expect(pw.response.status).toBe(200); });
pw.test("code place_list", () => { pw.expect(pw.response.body.code).toBe("place_list"); });
const data = pw.response.body.data;
pw.test("todo lo devuelto respeta los filtros", () => { data.forEach(pl => { pw.expect(pl.specialty).toBe(pw.env.get("SPECIALTY")); pw.expect(pl.zone).toBe(pw.env.get("ZONE")); }); });

pw.test("status 200", () => { pw.expect(pw.response.status).toBe(200); });
const m = pw.response.body.meta.pagination;
pw.test("respeta la pagina pedida", () => { pw.expect(String(m.page)).toBe(pw.env.get("PAGE")); });
pw.test("respeta el tamano pedido", () => { pw.expect(String(m.pageSize)).toBe(pw.env.get("PAGE_SIZE")); });

pw.test("status 200", () => { pw.expect(pw.response.status).toBe(200); });
const data = pw.response.body.data;
pw.test("hay al menos un registro para inspeccionar", () => { pw.expect(data.length > 0).toBe(true); });
pw.test("cada registro declara su frescura", () => { data.forEach(pl => { pw.expect(typeof pl.stale).toBe("boolean"); pw.expect(typeof pl.collectedAt).toBe("string"); }); });
pw.test("cada registro conserva la keyword que lo origino", () => { data.forEach(pl => pw.expect(typeof pl.sourceKeyword).toBe("string")); });

pw.test("status 400", () => { pw.expect(pw.response.status).toBe(400); });
pw.test("code validation_error", () => { pw.expect(pw.response.body.code).toBe("validation_error"); });
pw.test("el detalle senala el campo pageSize", () => { pw.expect(pw.response.body.errors.details.some(d => d.field === "pageSize")).toBe(true); });
pw.test("el detalle dice fuera de rango", () => { pw.expect(pw.response.body.errors.details.some(d => d.code === "out_of_range")).toBe(true); });

pw.test("status 400", () => { pw.expect(pw.response.status).toBe(400); });
pw.test("code validation_error", () => { pw.expect(pw.response.body.code).toBe("validation_error"); });
pw.test("el detalle senala el campo zone", () => { pw.expect(pw.response.body.errors.details.some(d => d.field === "zone")).toBe(true); });

pw.test("status 201", () => { pw.expect(pw.response.status).toBe(201); });
pw.test("code place_import_created", () => { pw.expect(pw.response.body.code).toBe("place_import_created"); });
const d = pw.response.body.data;
pw.test("no supera el tope de 2 paginas", () => { pw.expect(d.pagesFetched <= 2).toBe(true); });
pw.test("no supera el tope de 20 resultados", () => { pw.expect(d.itemsFetched <= 20).toBe(true); });
pw.test("el resumen corresponde a la keyword enviada", () => { pw.expect(d.keyword).toBe(pw.env.get("KEYWORD")); });
pw.test("informa los conflictos de especialidad", () => { pw.expect(Array.isArray(d.specialtyConflicts)).toBe(true); });

pw.test("status 400", () => { pw.expect(pw.response.status).toBe(400); });
pw.test("code validation_error", () => { pw.expect(pw.response.body.code).toBe("validation_error"); });
pw.test("el detalle nombra los campos que faltan", () => { pw.expect(pw.response.body.errors.details.length > 0).toBe(true); });
